package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;import java.util.*;import org.json.*;
public final class Stage48Instrumentation extends Instrumentation{
 void check(boolean b,String s){if(!b)throw new AssertionError(s);}void note(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 BananaEngine.Result run(Context c,Semilla m,String q)throws Exception{return BananaEngine.run(c,q,new ArrayList<String[]>(),"",true,m);}
 @Override public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();ModularHub.prefs(c).edit().clear().commit();ModularHub.loaded=-1;ModularHub.restore(c);AdaptiveMemory.prefs(c).edit().clear().commit();AdaptiveMemory.loaded=-1;AdaptiveMemory.restore(c);AppJavaWorkspace.prefs(c).edit().clear().commit();AppJavaWorkspace.loaded=-1;AppJavaWorkspace.restore(c);c.getSharedPreferences("shared-scene",0).edit().clear().commit();Semilla model=OwnBrain.load(c);run(c,model,"crea a Fito un zorro");String before=SceneStore.load(c).json().toString();int apk=c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode;
  BananaEngine.Result r=run(c,model,"prepara actualizacion modular: pone el tema de la app violeta; agranda el texto del chat; respuesta \"hola taller\" => \"Taller listo\"; comportamiento fiesta: salta y aplaude; herramienta \"Estudio\" con \"Personajes\" para \"mis personajes\"");check(r.text.contains("Preparé")&&ModularHub.view().text==15&&before.equals(SceneStore.load(c).json().toString()),"prepared hot package isolated");run(c,model,"aplica actualizacion modular");check(ModularHub.view().text==17&&ModularHub.view().theme==3&&ModularHub.active.panels.length()==1&&run(c,model,"hola taller").text.equals("Taller listo"),"atomic package drives UI, panel and actual chat");r=run(c,model,"Fito fiesta");check(r.changed&&r.scene.actions.contains("salta")&&r.scene.actions.contains("aplaude"),"new behavior applied to actual project");String after=SceneStore.load(c).json().toString();r=run(c,model,"prepara actualizacion modular: agranda el texto del chat; instala un dragon");check(r.text.contains("No activé")&&ModularHub.view().text==17&&after.equals(SceneStore.load(c).json().toString()),"invalid batch changes nothing");ModularHub.loaded=-1;ModularHub.active=null;ModularHub.restore(c);check(ModularHub.view().text==17&&ModularHub.reply("hola taller").equals("Taller listo"),"package survives reload");run(c,model,"deshace actualizacion modular");check(ModularHub.view().text==15&&ModularHub.reply("hola taller")==null&&after.equals(SceneStore.load(c).json().toString()),"all modular changes undone without deleting project");check(apk==c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode,"no APK installation by hot updates");note("NATIVE_HOT_PACKAGE_CHAT_SCENE_PANELS_RELOAD_AND_ROLLBACK_OK");
  r=run(c,model,"aprende esta respuesta: \"cual es la clave del taller\" => \"La clave es frutal\"");check(r.text.contains("Entrené")&&AdaptiveMemory.cached.rows.length()==1,"own retriever automatically trained");float sum=0;for(float value:AdaptiveMemory.cached.weights[0])sum+=Math.abs(value);check(sum>0,"learned parameters really change");r=run(c,model,"cual es la clave del taller");check(r.text.contains("La clave es frutal")&&r.text.contains("aporte del usuario"),"actual chatbot recalls explicit user evidence");run(c,model,"anota esta correccion: La clave es estrella");check(run(c,model,"cual es la clave del taller").text.contains("estrella"),"ordinary correction retrains and changes next answer");r=run(c,model,"aprende esta variante: \"como es la clave del taller\" para \"cual es la clave del taller\"");check(r.text.contains("variantes apartadas: 1/1"),"heldout variant evaluated without training on it");check(AdaptiveMemory.reply(c,"cual no es la clave del taller")==null&&AdaptiveMemory.reply(c,"donde viven las ballenas")==null,"conservative unknown and negation gates");AdaptiveMemory.loaded=-1;AdaptiveMemory.cached=null;AdaptiveMemory.restore(c);check(run(c,model,"como es la clave del taller").text.contains("estrella"),"learned model weights reload");note("NATIVE_TRAINING_CORRECTION_HELDOUT_AND_PERSISTENCE_OK");
  run(c,model,"pausa autoaprendizaje");run(c,model,"aprende esta respuesta: \"cual es el color del taller\" => \"Azul\"");check(AdaptiveMemory.cached.rows.length()==1&&AdaptiveMemory.data(c).length()==2,"pause leaves active model unchanged");run(c,model,"entrena mis correcciones");check(AdaptiveMemory.cached.rows.length()==2,"pending data explicitly trained");run(c,model,"deshace ultimo aprendizaje");check(AdaptiveMemory.cached.rows.length()==1&&AdaptiveMemory.data(c).length()==1,"learning rollback restores old data and weights");run(c,model,"activa autoaprendizaje");check(after.equals(SceneStore.load(c).json().toString()),"learning does not mutate scene");check(apk==c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode,"learning works without new package install");result.putString("stream","PASS STAGE48 same-install atomic modules across UI, chat, scenes and panels; local parameter training, automatic correction reuse, heldout evaluation, conservative recall, persistence, pause and version recovery.\n");finish(Activity.RESULT_OK,result);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,result);}}
}
